<script setup lang="ts">
import { formatTanggalWib, tanggalHariIniWib } from '~~/shared/utils/waktu'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '~/components/ui/card'
import { Button } from '~/components/ui/button'
import { NativeSelect, NativeSelectOption } from '~/components/ui/native-select'
import { Badge } from '~/components/ui/badge'
import { Skeleton } from '~/components/ui/skeleton'

definePageMeta({ layout: 'dashboard', title: 'Peringkat' })
const tab = ref<'upt' | 'kecamatan' | 'desa'>('upt')
const modePeriode = ref<'bulan_ini' | 'tahun_ini' | 'kustom'>('bulan_ini')
const hariIni = tanggalHariIniWib()
const mulaiKustom = ref(`${hariIni.slice(0, 7)}-01`)
const selesaiKustom = ref(hariIni)
const hanyaNonDbi = ref(false)
const periode = computed(() => modePeriode.value === 'bulan_ini' ? { mulai: `${hariIni.slice(0, 7)}-01`, selesai: hariIni } : modePeriode.value === 'tahun_ini' ? { mulai: `${hariIni.slice(0, 4)}-01-01`, selesai: hariIni } : { mulai: mulaiKustom.value, selesai: selesaiKustom.value })
const { data, pending, error, refresh } = await usePeringkatKanwil(computed(() => ({ ...periode.value, hanyaNonDbi: tab.value === 'desa' && hanyaNonDbi.value })))
const tabs = [{ id: 'upt', label: 'UPT' }, { id: 'kecamatan', label: 'Kecamatan' }, { id: 'desa', label: 'Desa' }] as const
const periodeLabel = computed(() => `${formatTanggalWib(`${periode.value.mulai}T00:00:00+07:00`)} – ${formatTanggalWib(`${periode.value.selesai}T00:00:00+07:00`)}`)
function warnaPeringkat(nilai: number) { return nilai === 1 ? 'bg-amber-100 text-amber-900' : nilai === 2 ? 'bg-amber-50 text-amber-800' : nilai === 3 ? 'bg-orange-50 text-orange-900' : 'bg-muted text-muted-foreground' }
</script>

<template>
  <div class="grid gap-5">
    <header class="flex flex-wrap items-end justify-between gap-4"><div><h2 class="text-2xl font-semibold tracking-tight">Peringkat wilayah</h2><p class="mt-1 text-sm text-muted-foreground">Rangkuman aktivitas dan laporan masyarakat · {{ periodeLabel }}</p></div><div class="flex flex-wrap items-end gap-3"><label class="grid gap-1.5 text-sm font-medium">Periode<NativeSelect v-model="modePeriode"><NativeSelectOption value="bulan_ini">Bulan ini</NativeSelectOption><NativeSelectOption value="tahun_ini">Tahun ini</NativeSelectOption><NativeSelectOption value="kustom">Rentang bebas</NativeSelectOption></NativeSelect></label><template v-if="modePeriode === 'kustom'"><label class="grid gap-1.5 text-sm font-medium">Dari<input v-model="mulaiKustom" class="h-9 rounded-md border border-input bg-background px-3 text-sm" type="date" :max="selesaiKustom"></label><label class="grid gap-1.5 text-sm font-medium">Sampai<input v-model="selesaiKustom" class="h-9 rounded-md border border-input bg-background px-3 text-sm" type="date" :min="mulaiKustom" :max="hariIni"></label></template></div></header>
    <div class="flex flex-wrap gap-2" role="tablist" aria-label="Jenis peringkat"><Button v-for="item in tabs" :key="item.id" role="tab" :aria-selected="tab === item.id" :variant="tab === item.id ? 'default' : 'outline'" @click="tab = item.id">{{ item.label }}</Button></div>
    <Card><CardHeader><CardTitle>{{ tab === 'upt' ? 'Peringkat UPT' : tab === 'kecamatan' ? 'Kecamatan dengan laporan terbanyak' : hanyaNonDbi ? 'Kandidat Desa Binaan Imigrasi' : 'Desa dengan laporan terbanyak' }}</CardTitle><CardDescription v-if="tab === 'upt'">Direspon berarti laporan pertama kali keluar dari status Diterima dalam periode ini, termasuk yang ditolak.</CardDescription><CardDescription v-else>{{ tab === 'desa' && hanyaNonDbi ? 'Desa yang belum menjadi DBI, diurutkan berdasarkan jumlah laporan.' : 'Urutan berdasarkan jumlah laporan masyarakat yang diterima.' }}</CardDescription><div v-if="tab === 'desa'" class="flex items-center gap-3 pt-2"><Button :variant="hanyaNonDbi ? 'default' : 'outline'" size="sm" role="switch" :aria-checked="hanyaNonDbi" @click="hanyaNonDbi = !hanyaNonDbi">{{ hanyaNonDbi ? 'Hanya non-DBI: aktif' : 'Hanya non-DBI: nonaktif' }}</Button><Badge variant="secondary">Kandidat DBI</Badge></div></CardHeader><CardContent>
      <div v-if="pending" class="grid gap-3"><Skeleton v-for="i in 5" :key="i" class="h-12 w-full" /></div>
      <div v-else-if="error" class="grid gap-3 text-sm text-destructive" role="alert">Peringkat belum dapat dimuat.<Button class="w-fit" variant="outline" @click="refresh()">Coba lagi</Button></div>
      <div v-else-if="tab === 'upt'" class="grid gap-5 lg:grid-cols-2"><section><h3 class="mb-3 font-semibold">Laporan kegiatan PIMPASA</h3><Table><TableHeader><TableRow><TableHead>Peringkat</TableHead><TableHead>UPT</TableHead><TableHead class="text-right">Kegiatan</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="item in data.upt" :key="item.kantor_id"><TableCell><Badge :class="warnaPeringkat(item.peringkat_kegiatan)">#{{ item.peringkat_kegiatan }}</Badge></TableCell><TableCell class="font-medium">{{ item.kantor }}</TableCell><TableCell class="text-right tabular-nums">{{ item.laporan_kegiatan }}</TableCell></TableRow><TableEmpty v-if="!data.upt.length" :colspan="3">Belum ada data UPT.</TableEmpty></TableBody></Table></section><section><h3 class="mb-3 font-semibold">Respons laporan masyarakat</h3><Table><TableHeader><TableRow><TableHead>Peringkat</TableHead><TableHead>UPT</TableHead><TableHead class="text-right">Direspon</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="item in data.upt" :key="item.kantor_id"><TableCell><Badge :class="warnaPeringkat(item.peringkat_respons)">#{{ item.peringkat_respons }}</Badge></TableCell><TableCell class="font-medium">{{ item.kantor }}</TableCell><TableCell class="text-right tabular-nums">{{ item.laporan_direspon }}</TableCell></TableRow><TableEmpty v-if="!data.upt.length" :colspan="3">Belum ada data respons.</TableEmpty></TableBody></Table></section></div>
      <Table v-else-if="tab === 'kecamatan'"><TableHeader><TableRow><TableHead>Peringkat</TableHead><TableHead>Kecamatan</TableHead><TableHead>Kabupaten/Kota</TableHead><TableHead class="text-right">Laporan</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="item in data.kecamatan" :key="item.kecamatan_id"><TableCell><Badge :class="warnaPeringkat(item.peringkat)">#{{ item.peringkat }}</Badge></TableCell><TableCell class="font-medium">{{ item.kecamatan }}</TableCell><TableCell>{{ item.kabupaten }}</TableCell><TableCell class="text-right tabular-nums">{{ item.jumlah_laporan }}</TableCell></TableRow><TableEmpty v-if="!data.kecamatan.length" :colspan="4">Belum ada laporan di periode ini.</TableEmpty></TableBody></Table>
      <Table v-else><TableHeader><TableRow><TableHead>Peringkat</TableHead><TableHead>Desa/Kelurahan</TableHead><TableHead>Kecamatan</TableHead><TableHead>Kabupaten/Kota</TableHead><TableHead>DBI</TableHead><TableHead class="text-right">Laporan</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="item in data.desa" :key="item.desa_id"><TableCell><Badge :class="warnaPeringkat(item.peringkat)">#{{ item.peringkat }}</Badge></TableCell><TableCell class="font-medium">{{ item.desa }}</TableCell><TableCell>{{ item.kecamatan }}</TableCell><TableCell>{{ item.kabupaten }}</TableCell><TableCell><Badge :variant="item.dbi ? 'default' : 'outline'">{{ item.dbi ? 'DBI' : '—' }}</Badge></TableCell><TableCell class="text-right tabular-nums">{{ item.jumlah_laporan }}</TableCell></TableRow><TableEmpty v-if="!data.desa.length" :colspan="6">Belum ada laporan di periode ini.</TableEmpty></TableBody></Table>
    </CardContent></Card>
  </div>
</template>
